from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(11,'mesures','Longueurs, masses, contenances','3 · Grandeurs et mesures',
'Conversions raisonnées · Estimations · Problèmes',
['Convertir en s’appuyant sur les relations entre unités.','Estimer des mesures avec des références fiables.','Résoudre des problèmes de mesures en plusieurs étapes.'],
['Unités du CM1 et décimaux jusqu’aux millièmes.'],[
page(1,'Les relations entre unités',
bloc('propriete',r'Longueurs : $1\ \mathrm{km}=1\,000\ \mathrm m$, $1\ \mathrm m=100\ \mathrm{cm}=1\,000\ \mathrm{mm}$. Masses : $1\ \mathrm t=1\,000\ \mathrm{kg}$, $1\ \mathrm{kg}=1\,000\ \mathrm g$, $1\ \mathrm g=1\,000\ \mathrm{mg}$. Contenances : $1\ \mathrm{hL}=100\ \mathrm L$, $1\ \mathrm L=100\ \mathrm{cL}=1\,000\ \mathrm{mL}$.'),
bloc('savoirfaire',r'Convertir, c’est citer la relation : $3{,}5$ m $=350$ cm car 1 m vaut 100 cm ; $0{,}75$ kg $=750$ g car 1 kg vaut $1\,000$ g ; $2\,500$ mL $=2{,}5$ L. Les millièmes rendent les conversions fines : 1 mm $=0{,}001$ m.','Convertir sans tableau'),
bloc('exemple',r'Références utiles : une porte 2 m, un grand pas 1 m, une pomme 150 g, une pièce de 1 euro $7{,}5$ g, une canette 33 cL, une baignoire 150 L, un litre d’eau pèse environ 1 kg.'),
bloc('attention',r'Comparer exige la même unité : $1{,}2$ km contre 980 m se joue en mètres. Une réponse s’écrit avec son unité, choisie pour rester lisible : 1 250 m se dit aussi $1{,}25$ km.')),
page(2,'Des mesures qui se combinent',
bloc('savoirfaire',r'Additionner des mesures : tout mettre dans la même unité d’abord. $1{,}2$ kg $+850$ g $=1\,200+850=2\,050$ g $=2{,}05$ kg.','Même unité avant tout'),
bloc('exemple',r'Un périmètre se calcule dans une unité unique : un champ de 125 m sur $87{,}5$ m a pour tour $2\times(125+87{,}5)=425$ m.'),
bloc('propriete',r'Les mesures se partagent : $1{,}5$ L réparti dans 6 verres donne $150:6=25$ cL par verre. Les relations entre unités transforment souvent une division décimale en division entière.'),
bloc('attention',r'Estimer avant de répondre : une baleine de 30 g, un cartable de 300 kg ou un verre de 20 L sont invraisemblables. La vraisemblance fait partie de la réponse.'))
],[
E('Relations à citer',r'Convertir en citant la relation utilisée : $3{,}5$ m en cm ; $0{,}75$ kg en g ; $2\,500$ mL en L.',r'1 m $=100$ cm : $\res{350}$ cm. 1 kg $=1\,000$ g : $\res{750}$ g. $1\,000$ mL $=1$ L : $\res{2{,}5}$ L.','Énoncer la relation avant le calcul.','assert Rational("3.5")*100==350 and Rational(".75")*1000==750 and Rational(2500,1000)==Rational("2.5")'),
E('Vers les millièmes',r'Convertir : 45 mm en m ; 3 g en kg ; 7 mL en L.',r'1 mm $=0{,}001$ m : $\res{0{,}045}$ m. $\res{0{,}003}$ kg. $\res{0{,}007}$ L.','Placer la mesure au rang des millièmes.','assert Rational(45,1000)==Rational(".045") and Rational(3,1000)==Rational(".003") and Rational(7,1000)==Rational(".007")'),
E('Comparer',r'Comparer : $1{,}2$ km et 980 m ; $0{,}5$ t et 520 kg ; 75 cL et $0{,}7$ L.',r'$1\,200>980$ : $\res{1{,}2\ \mathrm{km}>980\ \mathrm m}$. $500<520$ : $\res{0{,}5\ \mathrm t<520\ \mathrm{kg}}$. $75>70$ : $\res{75\ \mathrm{cL}>0{,}7\ \mathrm L}$.','Convertir dans la plus petite unité.','assert 1200>980 and 500<520 and 75>70'),
E('Estimations',r'Choisir la mesure vraisemblable : masse d’un vélo (12 kg ou 120 kg ?) ; contenance d’une tasse (25 cL ou 25 L ?) ; longueur d’une salle de classe (8 m ou 80 m ?).',r'Un vélo : $\res{12\ \mathrm{kg}}$. Une tasse : $\res{25\ \mathrm{cL}}$. Une salle : $\res{8\ \mathrm m}$.','Comparer aux références connues.','assert 12<120 and 25<2500 and 8<80'),
E('Additionner des mesures',r'Calculer : $1{,}2$ kg $+$ 850 g, en grammes puis en kilogrammes.',r'$1\,200+850=\res{2\,050}$ g, soit $\res{2{,}05}$ kg.','Convertir avant d’additionner.','assert 1200+850==2050 and Rational(2050,1000)==Rational("2.05")'),
E('Le tour du champ',r'Un champ rectangulaire mesure 125 m sur $87{,}5$ m. Calculer son périmètre, en mètres puis en kilomètres.',r'$2\times(125+87{,}5)=2\times212{,}5=\res{425}$ m, soit $\res{0{,}425}$ km.','Même unité pour tous les côtés.','assert 2*(125+Rational("87.5"))==425 and Rational(425,1000)==Rational(".425")'),
E('La carafe et les verres',r'Une carafe contient $1{,}5$ L. On remplit 6 verres identiques en la vidant exactement. Quelle est la contenance d’un verre, en centilitres ?',r'$1{,}5$ L $=150$ cL et $150:6=\res{25}$ cL par verre.','Convertir pour diviser des entiers.','assert 150//6==25'),
E('Le colis à la poste',r'Un colis contient 3 livres de 650 g chacun et un emballage de 120 g. Peut-on l’envoyer au tarif « moins de 2 kg » ?',r'Livres : $650\times3=1\,950$ g ; total $1\,950+120=\res{2\,070}$ g $=2{,}07$ kg. $2\,070>2\,000$ : $\res{\text{non}}$, il dépasse de 70 g.','Tout convertir en grammes.','assert 650*3==1950 and 1950+120==2070 and 2070>2000'),
E('L’eau de la semaine',r'Une famille boit 2 packs de 6 bouteilles de $1{,}5$ L par semaine. Quel volume d’eau cela fait-il ? Combien de litres par jour, en moyenne régulière sur 7 jours ? Donner une valeur approchée au dixième.',r'$2\times6=12$ bouteilles, soit $12\times1{,}5=\res{18}$ L. Par jour : $18:7\approx\res{2{,}6}$ L, car $7\times2{,}6=18{,}2$, proche de 18. La division exacte ne tombe pas juste : on arrondit.','Multiplier avant de partager.','assert 12*Rational("1.5")==18 and abs(Rational(18,7)-Rational("2.6"))<Rational(1,20)'),
E('Le médicament',r'Un flacon de sirop contient 200 mL. La dose est de 5 mL, trois fois par jour. Combien de jours complets le flacon dure-t-il ?',r'Par jour : $5\times3=15$ mL. $200=15\times13+5$ : le flacon dure $\res{13}$ jours complets, et il reste 5 mL.','Calculer la consommation quotidienne d’abord.','assert 5*3==15 and divmod(200,15)==(13,5)'),
E('La citerne du jardin',r'Une citerne de 3 hL est pleine. On arrose avec 12 arrosoirs de 9 L, puis on remplit un bassin de 150 L. Quelle contenance d’eau reste-t-il ?',r'$3$ hL $=300$ L. Arrosage : $12\times9=108$ L. Reste : $300-108-150=\res{42}$ L.','Suivre les retraits dans l’ordre.','assert 3*100==300 and 12*9==108 and 300-108-150==42'),
E('Les sacs de farine',r'Un boulanger reçoit $0{,}5$ t de farine en sacs de 25 kg. Combien de sacs reçoit-il ?',r'$0{,}5$ t $=500$ kg et $25\times20=500$ : il reçoit $\res{20}$ sacs.','Convertir la tonne avant de compter les sacs.','assert Rational(".5")*1000==500 and 25*20==500'),
E('Le ruban exact',r'Pour un paquet, il faut 65 cm de ruban. Combien de paquets complets prépare-t-on avec une bobine de 5 m ? Quelle longueur reste-t-il ?',r'5 m $=500$ cm ; $500=65\times7+45$ : $\res7$ paquets et il reste $\res{45}$ cm.','Travailler en centimètres.','assert divmod(500,65)==(7,45)'),
E('La tonne en question',r'Un ascenseur de chantier accepte $0{,}8$ t. On veut monter 15 sacs de ciment de 35 kg et 4 seaux de 12 kg chacun. Est-ce possible en un seul voyage ?',r'Sacs : $15\times35=525$ kg ; seaux : $4\times12=48$ kg ; total $\res{573}$ kg. La limite vaut 800 kg : $573<800$, c’est $\res{\text{possible}}$.','Comparer le total à la limite convertie.','assert 15*35==525 and 4*12==48 and 525+48==573 and 573<800'),
E('L’étiquette douteuse',r'Une étiquette annonce : « Bouteille de 75 cL, soit $7{,}5$ L ». Corriger l’erreur et donner la bonne équivalence en litres et en millilitres.',r'$75$ cL $=\res{0{,}75}$ L, et non $7{,}5$ L : l’étiquette confond les rangs. En millilitres : $\res{750}$ mL.','Citer la relation 100 cL = 1 L.','assert Rational(75,100)==Rational(".75") and 75*10==750')
],reperes=['Relations et conversions','Estimations et vraisemblance','Mesures combinées','Problèmes à étapes'],deco='grandeurs')

chapitre(12,'aires','Les aires : unités et formules','3 · Grandeurs et mesures',
'Comparaisons · cm², dm², m² · Carré et rectangle',
['Comparer et mesurer des aires par pavage.','Connaître et convertir les unités d’aire usuelles.','Calculer l’aire d’un carré et d’un rectangle.'],
['Aires par comptage (CM1) et multiplication des décimaux.'],[
page(1,'Des carreaux aux unités officielles',
bloc('definition',r'Le centimètre carré ($\mathrm{cm}^2$) est l’aire d’un carré de 1 cm de côté. Le décimètre carré ($\mathrm{dm}^2$) et le mètre carré ($\mathrm m^2$) suivent la même idée : carrés de 1 dm et de 1 m de côté.'),
r'@FIG:cours-dm2@',
bloc('propriete',r'Dans un carré de 1 dm de côté, on range 10 rangées de 10 petits carrés de 1 cm : $1\ \mathrm{dm}^2=100\ \mathrm{cm}^2$. De même, $1\ \mathrm m^2=100\ \mathrm{dm}^2$. D’une unité d’aire à la suivante, le rapport est 100, pas 10.'),
bloc('savoirfaire',r'Convertir : $3\ \mathrm{dm}^2=300\ \mathrm{cm}^2$ ; $4{,}5\ \mathrm m^2=450\ \mathrm{dm}^2$ ; $200\ \mathrm{cm}^2=2\ \mathrm{dm}^2$. Citer le rapport 100 à chaque étape.','Convertir des aires')),
page(2,'Les formules du carré et du rectangle',
bloc('propriete',r'L’aire d’un rectangle est longueur $\times$ largeur, mesurées dans la même unité : un rectangle de 7 cm sur 4 cm pave $7\times4=28$ carreaux de $1\ \mathrm{cm}^2$. L’aire du carré est côté $\times$ côté.'),
bloc('exemple',r'Un carré de 6 cm de côté : aire $6\times6=36\ \mathrm{cm}^2$ et périmètre $4\times6=24$ cm. Les deux grandeurs ne se confondent pas : l’une pave, l’autre entoure.'),
bloc('savoirfaire',r'Pour une figure en L, découper en rectangles : un L de côtés 8 et 6 avec une encoche de 5 sur 4 se traite par différence : $8\times6-5\times4=28$ unités d’aire, ou par découpage en deux rectangles.','Découper ou compléter'),
bloc('attention',r'Les longueurs doivent partager la même unité avant la formule : 2 m sur 50 cm, c’est $200\times50=10\,000\ \mathrm{cm}^2$, soit $1\ \mathrm m^2$, et non « $2\times50=100$ ».'))
],[
E('Compter puis calculer',r'Un rectangle quadrillé compte 4 rangées de 7 carreaux de $1\ \mathrm{cm}^2$. Donner son aire par comptage, puis par la formule.',r'Comptage : 4 rangées de 7, soit $\res{28}$ carreaux. Formule : $7\times4=\res{28\ \mathrm{cm}^2}$ : la formule résume le pavage.','Relier rangées et produit.','assert 4*7==28',figure='aire-1'),
E('Carré et rectangle',r'Calculer l’aire d’un carré de 6 cm de côté, puis d’un rectangle de 9 cm sur $4{,}5$ cm.',r'Carré : $6\times6=\res{36\ \mathrm{cm}^2}$. Rectangle : $9\times4{,}5=\res{40{,}5\ \mathrm{cm}^2}$.','Multiplier les deux dimensions.','assert 6*6==36 and 9*Rational("4.5")==Rational("40.5")'),
E('Aire ou périmètre ?',r'Pour un carré de 6 cm de côté, calculer le périmètre et l’aire, puis préciser l’unité de chacun.',r'Périmètre : $4\times6=\res{24}$ cm, une longueur. Aire : $6\times6=\res{36}\ \mathrm{cm}^2$, une surface. Deux grandeurs, deux unités.','Associer chaque formule à sa grandeur.','assert 4*6==24 and 6*6==36'),
E('Les conversions',r'Convertir : $3\ \mathrm{dm}^2$ en $\mathrm{cm}^2$ ; $4{,}5\ \mathrm m^2$ en $\mathrm{dm}^2$ ; $200\ \mathrm{cm}^2$ en $\mathrm{dm}^2$.',r'Le rapport est 100 : $\res{300\ \mathrm{cm}^2}$ ; $\res{450\ \mathrm{dm}^2}$ ; $\res{2\ \mathrm{dm}^2}$.','Multiplier ou diviser par 100.','assert 3*100==300 and Rational("4.5")*100==450 and 200/100==2'),
E('Pourquoi 100 ?',r'Expliquer pourquoi $1\ \mathrm{dm}^2=100\ \mathrm{cm}^2$ alors que $1$ dm $=10$ cm.',r'Le carré de 1 dm de côté contient $\res{10}$ rangées de $\res{10}$ carreaux de 1 cm : $10\times10=\res{100}$ carreaux. L’aire croise deux longueurs : le rapport 10 se multiplie par lui-même.','Paver le grand carré par les petits.','assert 10*10==100',figure='aire-5'),
E('Retrouver un côté',r'L’aire d’un rectangle vaut $54\ \mathrm{cm}^2$ et sa longueur 9 cm. Quelle est sa largeur ? Et le côté d’un carré de $49\ \mathrm{cm}^2$ ?',r'Largeur : $54:9=\res6$ cm. Pour le carré : $7\times7=49$, donc côté $\res7$ cm.','Défaire la multiplication.','assert 54//9==6 and 7*7==49'),
E('La figure en L',r'Une pièce en L s’obtient en retirant un rectangle de 5 m sur 4 m d’un rectangle de 8 m sur 6 m. Calculer son aire de deux façons.',r'Par différence : $8\times6-5\times4=48-20=\res{28\ \mathrm m^2}$. Par découpage : un rectangle $8\times2=16$ et un rectangle $3\times4=12$ : $16+12=28\ \mathrm m^2$ aussi.','Compléter ou découper, puis comparer.','assert 8*6-5*4==28 and 8*2+3*4==28',figure='aire-7'),
E('Les unités d’abord',r'Calculer l’aire d’un rectangle de 2 m sur 50 cm, en $\mathrm{cm}^2$ puis en $\mathrm m^2$.',r'En centimètres : $200\times50=\res{10\,000\ \mathrm{cm}^2}$. Or $1\ \mathrm m^2=10\,000\ \mathrm{cm}^2$ : l’aire vaut $\res{1\ \mathrm m^2}$. La demi-longueur compense le double mètre.','Convertir avant la formule.','assert 200*50==10000 and 100*100==10000'),
E('Même périmètre, aires rangées',r'Trois rectangles ont un périmètre de 20 cm : $9\times1$, $7\times3$ et $5\times5$. Vérifier, puis les ranger par aire croissante.',r'Périmètres : $2\times(9+1)=2\times(7+3)=2\times(5+5)=20$ cm. Aires : $9$, $21$ et $25\ \mathrm{cm}^2$ : $\res{9<21<25}$. À périmètre fixé, le carré offre la plus grande aire.','Calculer les deux grandeurs séparément.','assert 2*(9+1)==2*(7+3)==2*(5+5)==20 and 9*1==9 and 7*3==21 and 5*5==25'),
E('Le carré agrandi',r'On triple le côté d’un carré de 4 cm. Par combien l’aire est-elle multipliée ?',r'Avant : $4\times4=16\ \mathrm{cm}^2$. Après : $12\times12=144\ \mathrm{cm}^2$. Rapport : $144:16=\res9$ : tripler le côté multiplie l’aire par $3\times3=9$.','Comparer les deux aires par leur quotient.','assert 4*4==16 and 12*12==144 and 144//16==9'),
E('La chambre à moquette',r'Une chambre rectangulaire mesure $4{,}2$ m sur $3{,}5$ m. La moquette coûte 18 euros le mètre carré. Calculer l’aire de la chambre puis le prix de la moquette.',r'Aire : $4{,}2\times3{,}5=\res{14{,}7\ \mathrm m^2}$. Prix : $14{,}7\times18=\res{264{,}60}$ euros.','Calculer l’aire avant le prix.','assert Rational("4.2")*Rational("3.5")==Rational("14.7") and Rational("14.7")*18==Rational("264.6")'),
E('Le potager et l’allée',r'Un terrain carré de 12 m de côté contient une allée rectangulaire de 12 m sur 2 m ; le reste est cultivé. Quelle surface est cultivée ?',r'Terrain : $12\times12=144\ \mathrm m^2$. Allée : $12\times2=24\ \mathrm m^2$. Cultivé : $144-24=\res{120\ \mathrm m^2}$.','Soustraire la partie non cultivée.','assert 12*12==144 and 12*2==24 and 144-24==120'),
E('Les dalles de la terrasse',r'Une terrasse rectangulaire mesure 6 m sur 4 m. On la pave avec des dalles carrées de 50 cm de côté. Combien de dalles faut-il ?',r'Une dalle couvre $50\times50=2\,500\ \mathrm{cm}^2$, soit $0{,}25\ \mathrm m^2$. Terrasse : $24\ \mathrm m^2$. Nombre : $24:0{,}25=\res{96}$ dalles ; en effet $12\times8=96$ dalles en comptant 12 par longueur et 8 par largeur.','Compter les dalles par rangées.','assert 6*4==24 and 12*8==96 and 96*Rational(".25")==24'),
E('Deux annonces',r'Deux appartements affichent : A « $45\ \mathrm m^2$ » et B « un rectangle de 9 m sur 5,2 m ». Lequel est le plus grand, et de combien ?',r'B : $9\times5{,}2=46{,}8\ \mathrm m^2$. B dépasse A de $46{,}8-45=\res{1{,}8\ \mathrm m^2}$.','Mettre les deux surfaces en m².','assert 9*Rational("5.2")==Rational("46.8") and Rational("46.8")-45==Rational("1.8")'),
E('Vrai ou faux ?',r'« Si deux rectangles ont la même aire, ils ont le même périmètre. » Trancher avec les rectangles $12\times3$ et $9\times4$.',r'Aires : $12\times3=36$ et $9\times4=36$ : égales. Périmètres : $2\times15=30$ et $2\times13=26$ : différents. L’affirmation est $\res{\text{fausse}}$.','Construire un contre-exemple chiffré.','assert 12*3==36 and 9*4==36 and 2*(12+3)==30 and 2*(9+4)==26')
],reperes=['Unités d’aire et conversions','Formules du carré et du rectangle','Figures composées','Aires, périmètres et prix'],deco='grandeurs')
